        RETURN;
    END

    IF (@sync_batch_size_tblMovementHistory IS NULL OR 
        (@sync_batch_size_tblMovementHistory IS NOT NULL AND @sync_batch_size_tblMovementHistory = 0))
    BEGIN
        SET @sync_batch_size_tblMovementHistory = 2147483647;
    END


    -- Get a list of the Owned/Assigned Entities and locate any newly inserted entities
    -- and/or any new entity site assignments (if assignable).
    SELECT TOP(@sync_batch_size_tblMovementHistory) WITH TIES [dbo].[tblMovementHistory].[MovementHistoryGuid],[dbo].[tblMovementHistory].[SiteGuid],[dbo].[tblMovementHistory].[Name],[dbo].[tblMovementHistory].[Node],[dbo].[tblMovementHistory].[InitiationCount],[dbo].[tblMovementHistory].[RecordType],[dbo].[tblMovementHistory].[TimeStamp],[dbo].[tblMovementHistory].[ParentGuid],[dbo].[tblMovementHistory].[AutoStart],[dbo].[tblMovementHistory].[AutoStartTime],[dbo].[tblMovementHistory].[AutoStop],[dbo].[tblMovementHistory].[AutoStopTime],[dbo].[tblMovementHistory].[CloseoutDataModifiedBy],[dbo].[tblMovementHistory].[CloseoutDensityProductInAir],[dbo].[tblMovementHistory].[CloseoutDensityProductObserved],[dbo].[tblMovementHistory].[CloseoutDensityProductObservedTime],[dbo].[tblMovementHistory].[CloseoutDensityProductStandard],[dbo].[tblMovementHistory].[CloseoutDensityProductStandardTime],[dbo].[tblMovementHistory].[CloseoutDensityProductStandardInAir],[dbo].[tblMovementHistory].[CloseoutLevelProduct],[dbo].[tblMovementHistory].[CloseoutLevelProductTime],[dbo].[tblMovementHistory].[CloseoutLevelWater],[dbo].[tblMovementHistory].[CloseoutMassLiquid],[dbo].[tblMovementHistory].[CloseoutPercentBsw],[dbo].[tblMovementHistory].[CloseoutRoofMass],[dbo].[tblMovementHistory].[CloseoutTankShellCorrection],[dbo].[tblMovementHistory].[CloseoutTemperatureAmbient],[dbo].[tblMovementHistory].[CloseoutTemperatureAmbientTime],[dbo].[tblMovementHistory].[CloseoutTemperatureDensity],[dbo].[tblMovementHistory].[CloseoutTemperatureProduct],[dbo].[tblMovementHistory].[CloseoutTime],[dbo].[tblMovementHistory].[CloseoutTransferGov],[dbo].[tblMovementHistory].[CloseoutTransferNsv],[dbo].[tblMovementHistory].[CloseoutTransferMassLiquid],[dbo].[tblMovementHistory].[CloseoutTransferVolumeWater],[dbo].[tblMovementHistory].[CloseoutVolumeBsw],[dbo].[tblMovementHistory].[CloseoutVolumeCorrectionFactor],[dbo].[tblMovementHistory].[CloseoutVolumeGrossObserved],[dbo].[tblMovementHistory].[CloseoutVol